function tone(raw){const a=rgb(raw);if(!a)return P.white;const [r,g,b]=a,max=Math.max(...a),min=Math.min(...a),l=.2126*r+.7152*g+.0722*b;if(l>205||max-min<30&&l>145)return P.white;if(r>g*1.14&&r>b*1.3&&max-min>55&&r>155)return P.orange;const distance=hex=>{const b=rgb(hex);return a.reduce((n,v,i)=>n+(v-b[i])**2,0);};return distance(P.blue)<distance(P.navy)?P.blue:P.navy;}
