const html=fs.readFileSync(path.join(root,'Marketing_calc.HTML'),'utf8');for(const m of html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi))trees.push({file:'Marketing_calc.HTML inline',tree:postcss.parse(m[1])});
