function scoped(selector,src){const marker=src==='assets/nomad360-seo.css'?'.intro-copy':src==='assets/nomad360-legal.css'?'.legal-article':'#home-screen';return postcss.list.comma(selector).map(s=>s.startsWith(':root')?s.replace(':root',':root:has('+marker+')'):/^html(?=[\s.:#>]|$)/.test(s)?s.replace(/^html/,'html:has('+marker+')'):/^body(?=[\s.:#>]|$)/.test(s)?s.replace(/^body/,'body:has('+marker+')'):'body:has('+marker+') '+s).join(',');}

