const rawCss=`/* TASK-10: generated by scripts/palette/build.cjs. Approved palette only.\n   Original selectors retain geometry and relative !important priority. UI foreground follows the actual\n   surface; status meaning also remains in its text, icons and attributes. */\n@layer nomad360-palette-important,nomad360-palette;\n@layer nomad360-palette-important {\n${priorityBody.join('\n')}\n}\n@layer nomad360-palette {\n:root{--p10-navy:${P.navy};--p10-white:${P.white};--p10-orange:${P.orange};--p10-blue:${P.blue};--p10-fg:${P.navy};--p10-line:${P.blue};--p10-muted:${P.blue};--p10-accent:${P.navy};color-scheme:only light}\nhtml,body{background-color:${P.white}!important}\nhtml,html body,html body *,html body *::before,html body *::after{transition-property:transform!important;color:var(--p10-fg)!important;border-color:var(--p10-line)!important;font-family:Inter,system-ui,sans-serif!important;box-shadow:none!important;text-shadow:none!important}\n${body.join('\n')}\nhtml body :is(input,select,textarea){background-color:${P.white}!important;--p10-fg:${P.navy}!important;--p10-line:${P.blue}!important;caret-color:${P.navy}!important;accent-color:${P.navy}!important}\nhtml body :is(input,textarea)::placeholder{color:${P.blue}!important}\nhtml body :is(button,a,input,select,textarea,summary,[tabindex]):focus-visible{outline:3px solid ${P.navy}!important;outline-offset:2px!important;box-shadow:0 0 0 7px ${P.white}!important}\nhtml body :is(button,input,select,textarea):disabled{border-style:dashed!important;cursor:not-allowed!important;opacity:1!important}\nhtml body svg [fill]:not([fill="none"]){fill:currentColor!important}\nhtml body svg [stroke]:not([stroke="none"]){stroke:currentColor!important}\nhtml body ::selection{background:${P.navy}!important;color:${P.white}!important}\nhtml body dialog::backdrop{background:${P.navy}!important}\nhtml body{scrollbar-color:${P.blue} ${P.white}}\nhtml body [class*="bg-gradient-"],html body [style*="gradient("]{background-image:none!